const DAY_MS = 24 * 60 * 60 * 1000;

const HOUR_MS = 60 * 60 * 1000;

function buildCommand() {
  const __args = [['daily'], 'Economy', 'Claim your daily reward', async ({ sock, from, msg, senderNumber, db }) => {
  const e = db.econ(senderNumber);
  if (Date.now() - e.lastDaily < DAY_MS) {
    const hrs = Math.ceil((DAY_MS - (Date.now() - e.lastDaily)) / HOUR_MS);
    return sock.sendMessage(from, { text: `⏳ Already claimed. Try again in ${hrs}h.` }, { quoted: msg });
  }
  e.balance += 200;
  e.lastDaily = Date.now();
  db.saveEcon();
  await sock.sendMessage(from, { text: `✅ Claimed daily reward: +200. Wallet: ${e.balance}` }, { quoted: msg });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
